---level20 script---local isPlayingDemo = falselocal countFail = 0local isSkip = truelocal hasViewedStory = global.getBool("lvl20_b1")if not hasViewedStory or not game.isRestart() then	repeat		if hasViewedStory then dialog.setSkipEnabled(true) end		game.setUserInputEnabled(false)		role.setIdleActionEnabled(false)		script.delay(1)		sound.play("44-1")		if dialog.show("Level20-1", faceJingya) ==1 then break end		camera.setFollowRoleMode(false)		camera.gotoPosition(620,440)		if dialog.show("Level20-2", faceZhoumei) ==1 then break end		sound.play("60-1")		if dialog.show("Level20-3", faceBujie) ==1 then break end		sound.play("60-4")		if dialog.show("Level20-4", faceWunai) ==1 then break end		if dialog.show("Level20-5", faceDeyi) ==1 then break end		camera.gotoRole()		sound.play("50-2")		if dialog.show("Level20-6", faceRenzhen) ==1 then break end		if dialog.showMinTime("Level20-7", faceZhoumei,0) ==1 then break end		sound.play("54-1")		if dialog.show("Level20-8", faceWeixiao) ==1 then break end		camera.setFollowRoleMode(true)				--set story viewed flag        global.setBool("lvl20_b1")		game.restartTiming()		game.setUserInputEnabled(true)		role.setIdleActionEnabled(true)		isPlayingDemo = false		isSkip = false	until trueendif isSkip then	camera.gotoRole()	camera.setFollowRoleMode(true)	dialog.setSkipEnabled(false)	game.resumeLogic()	game.showTutorialDiagram(0)	game.setUserInputEnabled(true)	role.setIdleActionEnabled(true)	game.restartTiming()end